function App() {
  const [showList, setShowList] = useState(true);
  const fruits = [
    { id: 1, name: 'Apple' },
    { id: 2, name: 'Banana' },
    { id: 3, name: 'Cherry' }
  ];
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setShowList(s => !s)}>
        {showList ? 'Hide' : 'Show'} fruits
      </button>
      {showList && (
        <>
          <h3>Fruit list</h3>
          <ul>
            {fruits.map(f => (
              <li key={f.id}>{f.name}</li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

