solution.code:
function App() {
  const tasks = ['Write JSX', 'Add keys', 'Use className'];
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Tasks</h2>
      <p>{tasks.length} tasks</p>
      <ul className="tasks">
        {tasks.map((t, i) => (
          <li key={i}>{t}</li>
        ))}
      </ul>
    </div>
  );
}

