function App() {
  return (
    <>
      <label className="field" htmlFor="name">Name</label>
      <input id="name" />
    </>
  );
}

function App() {
  const users = [
    { id: 'a1', name: 'Ada' },
    { id: 'b2', name: 'Linus' }
  ];
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Users</h2>
      {users.length === 0 ? (
        <p>No users</p>
      ) : (
        <ul>
          {users.map(u => (
            <li key={u.id}>{u.name}</li>
          ))}
        </ul>
      )}
    </div>
  );
}
